from pydantic import BaseModel  
from typing import List, Optional, Dict, Any  
from enum import Enum  
from abc import abstractmethod  

from system.message import Info  
from system.message import BaseMessageDataType  
from model.strategy_type import StrategyType  
from model.base import BaseStrategy  


class SudoKillCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        # grid is list of list, with each list is int     
        grid = message.message[0].data[1]
        # prev_move is [(row_index, col_index), value], if you are the first move, it is None
        prev_move = message.message[0].data[0]
        # return the decision with the format [(row_index, col_index), value]
        move = None
        n = len(grid)

        def is_valid(grid, row, col, num):
            # Check row
            for x in range(n):
                if grid[row][x] == num:
                    return False
            # Check column
            for x in range(n):
                if grid[x][col] == num:
                    return False
            # Check 3x3 box
            start_row = (row // 3) * 3
            start_col = (col // 3) * 3
            for i in range(3):
                for j in range(3):
                    if grid[start_row + i][start_col + j] == num:
                        return False
            return True

        def find_empty_location(grid):
            for i in range(n):
                for j in range(n):
                    if grid[i][j] == 0:
                        return (i, j)
            return None

        if prev_move is None:
            for i in range(n):
                for j in range(n):
                    if grid[i][j] == 0:
                        for num in range(1, n + 1):
                            if is_valid(grid, i, j, num):
                                move = [(i, j), num]
                                return Info(
                                    sender=self.__class__.__name__,
                                    receiver=message.sender,
                                    difficulty=message.difficulty,
                                    message=[BaseMessageDataType(data=move, type='custom')]
                                )
        else:
            row, col = prev_move[0]

            # Check cells in the same row
            for j in range(n):
                if grid[row][j] == 0:
                    for num in range(1, n + 1):
                        if is_valid(grid, row, j, num):
                            move = [(row, j), num]
                            return Info(
                                sender=self.__class__.__name__,
                                receiver=message.sender,
                                difficulty=message.difficulty,
                                message=[BaseMessageDataType(data=move, type='custom')]
                            )
            # Check cells in the same column
            for i in range(n):
                if grid[i][col] == 0:
                    for num in range(1, n + 1):
                        if is_valid(grid, i, col, num):
                            move = [(i, col), num]
                            return Info(
                                sender=self.__class__.__name__,
                                receiver=message.sender,
                                difficulty=message.difficulty,
                                message=[BaseMessageDataType(data=move, type='custom')]
                            )

            # If no cells in the same row or column, search the entire board
            for i in range(n):
                for j in range(n):
                    if grid[i][j] == 0:
                        for num in range(1, n + 1):
                            if is_valid(grid, i, j, num):
                                move = [(i, j), num]
                                return Info(
                                    sender=self.__class__.__name__,
                                    receiver=message.sender,
                                    difficulty=message.difficulty,
                                    message=[BaseMessageDataType(data=move, type='custom')]
                                )

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=None, type='custom')]
        )

