        def is_valid(grid, row, col, num):
            # Check row
            for i in range(9):
                if grid[row][i] == num:
                    return False
            # Check column
            for i in range(9):
                if grid[i][col] == num:
                    return False
            # Check 3x3 subgrid
            start_row = (row // 3) * 3
            start_col = (col // 3) * 3
            for i in range(3):
                for j in range(3):
