                        return False
            return True

        def get_possible_moves(grid, prev_move):
            possible_moves = []
            for row in range(9):
                for col in range(9):
                    if grid[row][col] == 0:
                        if prev_move is None:
                            possible_moves.append(((row, col), 1))
                        else:
                            prev_row, prev_col = prev_move[0]
                            if row == prev_row or col == prev_col:
                                for num in range(1, 10):
                                    if is_valid(grid, row, col, num):
                                        possible_moves.append(((row, col), num))
            if not possible_moves and prev_move is not None:
                for row in range(9):
                    for col in range(9):
                        if grid[row][col] == 0:
                            for num in range(1, 10):
                                if is_valid(grid, row, col, num):
                                    possible_moves.append(((row, col), num))
            return possible_moves

        def check_win(grid, move):
            row, col = move[0]
            val = move[1]
            temp_grid = [row[:] for row in grid]
            temp_grid[row][col] = val

            possible_opponent_moves = []
            for r in range(9):
                for c in range(9):
                    if temp_grid[r][c] == 0:
                        if move is None:
                            possible_opponent_moves.append(((r, c), 1))
                        else:
                            if r == row or c == col:
                                for num in range(1, 10):
                                    if is_valid(temp_grid, r, c, num):
                                        possible_opponent_moves.append(((r, c), num))

            if not possible_opponent_moves:
                return True
            else:
                return False

        possible_moves = get_possible_moves(grid, prev_move)

        for possible_move in possible_moves:
            if check_win(grid, possible_move):
                move = possible_move
                break

        if move is None and possible_moves:
            move = possible_moves[0]

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=move, type='custom')]
        )

