    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        # grid is list of list, with each list is int
        grid = message.message[0].data[1]
        # prev_move is [(row_index, col_index), value], if you are the first move, it is None
        prev_move = message.message[0].data[0]
        # return the decision with the format [(row_index, col_index), value]
        move = None

        n = len(grid)

        def is_valid(grid, row, col, num):
            # Check row
            for i in range(n):
                if grid[row][i] == num:
                    return False

            # Check column
            for i in range(n):
                if grid[i][col] == num:
                    return False

            # Check 3x3 subgrid
            sqrt_n = int(n**0.5)
            start_row = row - row % sqrt_n
            start_col = col - col % sqrt_n
            for i in range(sqrt_n):
                for j in range(sqrt_n):
                    if grid[i + start_row][j + start_col] == num:
                        return False

            return True

        if prev_move is None:
            # First move: find the first empty cell and fill it
            for i in range(n):
                for j in range(n):
                    if grid[i][j] == 0:
                        for num in range(1, n + 1):
                            if is_valid(grid, i, j, num):
                                move = [(i, j), num]
                                return Info(
                                    sender=self.__class__.__name__,
                                    receiver=message.sender,
                                    difficulty=message.difficulty,
                                    message=[BaseMessageDataType(data=move, type='custom')]
                                )
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=None, type='custom')]
            )
        else:
            last_row, last_col = prev_move[0]
            last_value = prev_move[1]

            # Try to find a move in the same row or column
            # First, check same row
            for j in range(n):
                if grid[last_row][j] == 0:
                    for num in range(1, n + 1):
                        if is_valid(grid, last_row, j, num):
                            # Check if this move leaves the opponent with only one option
                            valid_options = []
                            for k in range(n):
                                if grid[last_row][k] == 0:
                                    for val in range(1, n + 1):
                                        if is_valid(grid, last_row, k, val):
                                            valid_options.append((last_row, k, val))

                            if len(valid_options) == 1:
                                move = [(last_row, j), num]
                                return Info(
                                    sender=self.__class__.__name__,
                                    receiver=message.sender,
                                    difficulty=message.difficulty,
                                    message=[BaseMessageDataType(data=move, type='custom')]
                                )

                            #check if move leaves opponent with two options
                            if len(valid_options) == 2:
                                move = [(last_row,j), num]
                                return Info(
                                    sender=self.__class__.__name__,
                                    receiver=message.sender,
                                    difficulty=message.difficulty,
                                    message=[BaseMessageDataType(data=move, type='custom')]
                                )

            # Then, check same column
            for i in range(n):
                if grid[i][last_col] == 0:
                    for num in range(1, n + 1):
                        if is_valid(grid, i, last_col, num):
                            # Check if this move leaves the opponent with only one option
                            valid_options = []
                            for k in range(n):
                                if grid[k][last_col] == 0:
                                    for val in range(1, n + 1):
                                        if is_valid(grid, k, last_col, val):
                                            valid_options.append((k, last_col, val))

                            if len(valid_options) == 1:
                                move = [(i, last_col), num]
                                return Info(
                                    sender=self.__class__.__name__,
                                    receiver=message.sender,
                                    difficulty=message.difficulty,
                                    message=[BaseMessageDataType(data=move, type='custom')]
                                )
                            #check if move leaves opponent with two options
                            if len(valid_options) == 2:
                                move = [(i,last_col), num]
                                return Info(
                                    sender=self.__class__.__name__,
                                    receiver=message.sender,
                                    difficulty=message.difficulty,
                                    message=[BaseMessageDataType(data=move, type='custom')]
                                )
            # If no restricting move found, fill the first empty cell
            for i in range(n):
                for j in range(n):
                    if grid[i][j] == 0:
                        for num in range(1, n + 1):
                            if is_valid(grid, i, j, num):
                                move = [(i, j), num]
                                return Info(
                                    sender=self.__class__.__name__,
                                    receiver=message.sender,
                                    difficulty=message.difficulty,
                                    message=[BaseMessageDataType(data=move, type='custom')]
                                )
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=None, type='custom')]
            )

